C_ROMS_CNCDH_2014 = ('c_roms_cncdh_2014', src("Avis sur le respect des droits fondamentaux des populations vivant en bidonvilles", "Commission nationale consultative des droits de l'homme (CNCDH)", '20 novembre 2014',
  'https://www.gisti.org/IMG/pdf/jur_cncdh_2014-11-20_bidonvilles.pdf',
  "Les Roms migrants vivant en bidonvilles sont estimés à « 15 000 à 20 000 personnes en France », soit environ 0,03 % de la population, un chiffre stable depuis dix ans. Un mode de vie nomade leur est attribué à tort : dans une enquête de la CNCDH, 86 % des personnes interrogées considéraient les Roms migrants comme surtout nomades. Les Roms sont souvent présentés comme un groupe « associé à l'insalubrité, à la délinquance et aux expédients » ; la focalisation médiatique sur la délinquance masque le fait que les mineurs des Balkans et d'Europe de l'Est sont d'abord victimes de traite.",
  "Avis officiel de la CNCDH (copie hébergée par le Gisti) ; données de 2014.", 'primaire'))
C_ROMS_DIHAL_2026 = ('c_roms_dihal_2026', src("Contribution de la Dihal au rapport 2025 de la CNCDH sur la lutte contre le racisme", "Délégation interministérielle à l'hébergement et à l'accès au logement (Dihal), publiée par la CNCDH", 'juin 2026',
  'https://www.cncdh.fr/sites/default/files/2026-06/Dihal_CNCDH_Contribution_2025.pdf',
  "Le nombre de personnes en bidonvilles « est aujourd'hui estimé à 10 000 personnes d'origine intra-européenne », principalement de Roumanie et de Bulgarie, en baisse d'environ 25 % depuis 2018 ; il s'agit de personnes « dites ou se considérant comme Roms ». En 2023, 1 248 personnes ont accédé à un emploi et 1 451 à un hébergement ou un logement grâce à la politique de résorption ; en 2024-2025, la médiation a permis de scolariser 3 900 enfants (1 430 en 2019).",
  "Contribution officielle d'une administration de l'État.", 'primaire'))
C_ROMS_AFP_2021 = ('c_roms_afp_2021', src("France : jusqu'à 8 ans de prison pour traite de mendiants roms bulgares", 'AFP, repris par The Times of Israel (édition française)', '10 février 2021',
  'https://fr.timesofisrael.com/france-jusqua-8-ans-de-prison-pour-traite-de-mendiants-roms-bulgares/amp/',
  "Le tribunal correctionnel de Toulouse a condamné 16 hommes roms originaires de Bulgarie pour traite d'êtres humains, exploitation de la mendicité et blanchiment, à des peines allant jusqu'à huit ans de prison. 33 mendiants ont été identifiés comme victimes : recrutés dans la région de Pleven avec la promesse d'un travail, ils se faisaient confisquer leurs papiers, devaient mendier de longues heures et remettre l'argent, et étaient mal nourris et parfois battus.",
  "Dépêche d'agence de presse.", 'secondaire'))
C_ROMS_CNCDH_2024 = ('c_roms_cncdh_2024', src("Avis sur la traite à des fins de contrainte à commettre tout délit ou crime (A-2024-2)", "Commission nationale consultative des droits de l'homme (CNCDH)", '28 mars 2024',
  'https://www.cncdh.fr/sites/default/files/2024-03/A%20-%202024%20-%202%20-%20Avis%20Contrainte%20%C3%A0%20commettre%20d%C3%A9lit%20ou%20crime%2C%20mars%202024.pdf',
  "En 2022, 195 victimes (7 %) sur les 2 675 accompagnées par 69 associations étaient contraintes à commettre des délits ou des crimes ; environ 70 % des victimes en France sont des mineurs non accompagnés ; 81 % étaient exploitées par une personne de leur entourage et 16 % par leur famille. Les vols à la tire sont un exemple de délinquance imposée. « ceux qui sont contraints à commettre un acte de délinquance sont en fait des victimes ». L'avis ne vise aucune origine particulière.",
  "Avis officiel de la CNCDH.", 'primaire'))

FICHES.append(fiche(
 id='roms-mendicite-vol', affirmation="Les Roms vivent de la mendicité et du vol.", volet='immigration', sous_theme='Racisme',
 mots_cles=['roms voleurs', 'roms mendicite', 'roms vivent du vol', 'roms delinquance', 'roms pickpockets', 'campements roms', 'gens du voyage voleurs', 'bidonvilles roms', 'tsiganes'],
 verdict='contredit', fiabilite='interpretation',
 resume="Contredit : c'est un préjugé qui vise tout un peuple, pas un constat. Selon la CNCDH, les Roms sont « de loin la minorité la moins acceptée » en France. L'image du campement et de la mendicité ne concerne qu'environ 10 000 personnes venues surtout de Roumanie et de Bulgarie, en grande pauvreté. Les « gens du voyage », souvent confondus avec elles, sont environ 500 000 personnes, en très grande majorité françaises, souvent sédentaires. Des réseaux d'exploitation existent et sont jugés ; leurs premières victimes sont souvent des Roms.",
 contexte="Les Roms sont l'objet d'un rejet particulier en France, régulièrement entretenu par des discours politiques et médiatiques. Le préjugé mélange des populations très différentes : des citoyens français itinérants ou sédentaires, et des migrants européens vivant en bidonvilles.",
 explication="Il faut distinguer qui sont les personnes visées, combien vivent réellement en bidonvilles, ce que mesurent les enquêtes sur les préjugés, et ce que disent les affaires de traite jugées.",
 sources=[C_ROMS_CNCDH_2026, C_ROMS_MAYER_2026, C_ROMS_MAIREINFO_2022, C_ROMS_CNCDH_2012, C_ROMS_CNCDH_2014, C_ROMS_DIHAL_2026, C_ROMS_AFP_2021, C_ROMS_CNCDH_2024],
 faits=[
  fait("Selon le rapport 2025 de la CNCDH, les Roms sont « de loin la minorité la moins acceptée » : 64 % des personnes interrogées les voient comme un groupe à part.", 'c_roms_cncdh_2026', '2025', 'France', "Le préjugé est massif et durable ; il vise un peuple entier.", 'etabli', '64 %'),
  fait("D'après le baromètre de la CNCDH rapporté par Maire-info, 45 % des personnes interrogées adhéraient en 2021 à l'idée que les Roms vivraient essentiellement de vols et de trafics.", 'c_roms_maireinfo_2022', '2021', 'France', "L'affirmation est un préjugé mesuré par les enquêtes sur le racisme, pas un constat statistique.", 'estimation', '45 %'),
  fait("Selon la Dihal, environ 10 000 personnes d'origine européenne, surtout roumaine et bulgare, vivent en bidonvilles en France, un nombre en baisse d'environ 25 % depuis 2018.", 'c_roms_dihal_2026', '2018-2025', 'France', "L'image du campement concerne un petit nombre de personnes, en très grande pauvreté.", 'etabli', '10 000'),
  fait("En 2023, la politique de résorption des bidonvilles a permis à 1 248 personnes d'accéder à un emploi et à 1 451 à un hébergement ou un logement ; 3 900 enfants ont été scolarisés grâce à la médiation en 2024-2025.", 'c_roms_dihal_2026', '2023-2025', 'France', "Quand on leur en donne les moyens, les habitants des bidonvilles travaillent et scolarisent leurs enfants.", 'etabli', '1 248'),
  fait("Selon la CNCDH, les gens du voyage représentaient environ 500 000 personnes en 2012, en très grande majorité de nationalité française et souvent sédentaires ; c'est une catégorie administrative distincte des Roms migrants.", 'c_roms_cncdh_2012', '2012', 'France', "Le préjugé confond des citoyens français et des migrants européens, qui n'ont ni le même mode de vie ni le même statut.", 'etabli', '500 000'),
  fait("Selon une enquête citée par la CNCDH, 86 % des personnes interrogées croyaient les Roms migrants surtout nomades, alors qu'ils étaient sédentaires avant leur arrivée en France.", 'c_roms_cncdh_2014', '2014', 'France', "L'image publique des Roms repose sur des idées fausses.", 'etabli', '86 %'),
  fait("Fait défavorable : en février 2021, le tribunal correctionnel de Toulouse a condamné 16 hommes roms originaires de Bulgarie, jusqu'à huit ans de prison, pour avoir exploité 33 mendiants recrutés dans leur région d'origine, privés de papiers et parfois battus.", 'c_roms_afp_2021', '2021', 'Toulouse', "Des réseaux d'exploitation de la mendicité existent et doivent être poursuivis ; leurs victimes viennent souvent des mêmes communautés pauvres.", 'etabli', '33'),
  fait("Selon la CNCDH, environ 70 % des victimes de traite contraintes à commettre des délits en France sont des mineurs non accompagnés, et 81 % sont exploitées par une personne de leur entourage ; l'avis ne vise aucune origine particulière.", 'c_roms_cncdh_2024', '2022', 'France', "Les enfants forcés à voler sont d'abord des victimes de traite, qu'il faut protéger.", 'etabli', '70 %'),
 ],
 court="C'est un préjugé contre tout un peuple : selon la CNCDH, les Roms sont « de loin la minorité la moins acceptée » en France. Les bidonvilles concernent environ 10 000 personnes très pauvres, et quand on leur en donne les moyens, elles travaillent. Les gens du voyage, souvent confondus avec eux, sont surtout des Français, souvent sédentaires.",
 moyen="Juger tout un peuple sur le comportement de certains, c'est la définition même du racisme. Et les chiffres montrent que ce préjugé est massif : selon la CNCDH, les Roms sont la minorité la moins acceptée en France, et en 2021, 45 % des personnes interrogées pensaient qu'ils vivent surtout de vols.\n\nLa réalité est différente. L'image du campement ne concerne qu'environ 10 000 personnes venues surtout de Roumanie et de Bulgarie, en très grande pauvreté. Quand l'État les accompagne, elles travaillent et scolarisent leurs enfants : 1 248 personnes ont trouvé un emploi en 2023. Les « gens du voyage », souvent confondus avec elles, sont environ 500 000 personnes, en très grande majorité françaises. Oui, des réseaux qui exploitent la mendicité ou forcent des enfants à voler existent et sont jugés, comme à Toulouse en 2021. Mais leurs premières victimes sont souvent des Roms eux-mêmes.",
 detaille="Cette phrase n'est pas un constat : c'est un préjugé qui attribue à tout un peuple les actes de quelques-uns. Les enquêtes sur le racisme le mesurent depuis longtemps. Selon le rapport 2025 de la CNCDH, les Roms sont « de loin la minorité la moins acceptée » en France, et 64 % des personnes interrogées les voient comme un groupe à part. En 2021, 45 % adhéraient à l'idée qu'ils vivraient essentiellement de vols et de trafics.\n\nLe préjugé confond des populations très différentes. Les « gens du voyage » sont une catégorie administrative française : environ 500 000 personnes selon la CNCDH en 2012, en très grande majorité françaises, dont beaucoup sont sédentaires. Les Roms migrants venus de Roumanie ou de Bulgarie sont beaucoup moins nombreux ; ceux qui vivent en bidonvilles sont estimés à environ 10 000 personnes par la Dihal, un nombre en baisse. Ce sont des personnes en très grande pauvreté. Quand l'État les accompagne, les résultats suivent : en 2023, 1 248 personnes ont accédé à un emploi et 1 451 à un logement ou un hébergement, et 3 900 enfants ont été scolarisés en 2024-2025.\n\nIl ne faut pas nier pour autant que des réseaux criminels existent. En 2021, le tribunal de Toulouse a condamné seize hommes roms venus de Bulgarie qui exploitaient la mendicité de trente-trois personnes, privées de papiers et parfois battues. La CNCDH rappelle que les enfants forcés à voler sont d'abord des victimes de traite. Combattre ces réseaux est nécessaire ; mais accuser tout un peuple, c'est confondre les victimes avec leurs exploiteurs.",
 empathie="Être témoin de vols à la tire ou de mendicité insistante peut être désagréable, voire inquiétant, et ce ressenti mérite d'être entendu. Mais il ne dit rien de tout un peuple.",
 legitimes=["Des réseaux d'exploitation de la mendicité ou de mineurs contraints à voler existent et doivent être poursuivis.", "Les bidonvilles posent de vrais problèmes d'hygiène et de sécurité, d'abord pour leurs habitants.", "Les élus locaux peuvent être démunis face aux installations illicites."],
 contre=[
  ("Moi, je l'ai vu dans le métro.", "Des vols à la tire existent et des réseaux sont jugés. Mais on ne juge pas des centaines de milliers de personnes sur ce qu'on a vu faire à quelques-unes ; et les enfants forcés à voler sont d'abord des victimes de traite."),
  ("Ils ne veulent pas travailler.", "Quand l'État accompagne les habitants des bidonvilles, ils accèdent à l'emploi : 1 248 personnes en 2023 selon la Dihal. Et les gens du voyage sont en très grande majorité des Français, souvent sédentaires."),
 ],
 questions=["Sais-tu combien de personnes vivent réellement en bidonvilles en France ?", "Fais-tu la différence entre les gens du voyage, qui sont en majorité français, et les Roms venus de Roumanie ?", "Si un réseau exploite des enfants pour voler, qui sont les coupables et qui sont les victimes ?"],
 limites=["Il n'existe pas de statistique ethnique en France : aucune source ne permet de mesurer les revenus ou la délinquance « des Roms ».", "Les estimations sur les gens du voyage datent de 2012 et celles sur les Roms migrants de 2014 ; le chiffre de 10 000 personnes en bidonvilles est plus récent mais porte sur les personnes d'origine européenne en général.", "Le chiffre de 45 % provient d'un compte rendu du rapport de la CNCDH de 2022 ; le rapport original n'a pas été ouvert.", "L'avis de la CNCDH sur la traite ne donne pas l'origine des victimes."],
 publics={'convaincus': "Les bidonvilles, c'est environ 10 000 personnes très pauvres, et quand on les accompagne, elles trouvent du travail. Les gens du voyage, eux, sont surtout des Français, souvent sédentaires. Oui, des réseaux qui exploitent des mendiants existent et sont condamnés, mais leurs premières victimes sont souvent des Roms : on ne juge pas tout un peuple sur ses pires éléments.",
  'indecis': "Ce que tu as pu voir dans la rue est réel, mais ça ne dit rien de tout un peuple. Selon la CNCDH, les Roms sont la minorité la plus rejetée en France, et le préjugé confond des citoyens français et des migrants très pauvres. Les réseaux d'exploitation existent et sont jugés ; leurs victimes ont besoin d'être protégées, pas soupçonnées."},
 a_actualiser='2027-07-31', raison="Rapport annuel de la CNCDH sur le racisme et nouvel état des lieux de la Dihal.",
))

# 5 ── « Les différences de QI entre pays prouvent que certains peuples sont moins intelligents » ──
C_QI_WICHERTS_2010 = ('c_qi_wicherts_2010', src("A systematic literature review of the average IQ of sub-Saharan Africans", 'Jelte M. Wicherts, Conor V. Dolan, Han L. J. van der Maas (université de Tilburg et université d’Amsterdam), revue Intelligence, vol. 38, n° 1, p. 1-20', '2010',
  'https://research.tilburguniversity.edu/en/publications/a-systematic-literature-review-of-the-average-iq-of-sub-saharan-a/',
  "Revue systématique des données publiées, avec des critères d'inclusion explicites. Lynn et Vanhanen avaient « concluded that the average IQ of the Black population of sub-Saharan Africa lies below 70 ». Les auteurs trouvent que « average IQ of Africans on these tests is approximately 82 when compared to UK norms » et estiment que « this estimate should be considered in light of the Flynn Effect ». Ils appellent à davantage de recherches sur les biais de mesure des tests occidentaux appliqués en Afrique.",
  "Article évalué par les pairs dans une revue spécialisée.", 'etude'))
C_QI_STAT_2024 = ('c_qi_stat_2024', src("Journals that published Richard Lynn's racist 'research' articles should retract them (tribune)", 'Dan Samorodnitsky, Kevin Bird, Jedidiah Carlson, James Lingford, Jon Phillips, Rebecca Sear, Cathryn Townsend — STAT', '20 juin 2024',
  'https://www.statnews.com/2024/06/20/richard-lynn-racist-research-articles-journals-retractions/',
  "« Lynn never published any sort of selection criteria or methodology ». Selon l'étude de Wicherts et al. (2010), Lynn a retenu les échantillons africains aux scores bas et écarté les plus élevés, et n'a utilisé aucun échantillon africain de moyenne supérieure à 85. La moitié des estimations nationales d'Afrique subsaharienne et d'Amérique latine reposent sur moins de 1 000 personnes : l'Angola sur 19 personnes pour un pays de 35 millions d'habitants. Les défauts persistent dans la version de 2019 (131 pays). Une revue de la Royal Society a rétracté un article fondé sur ces données ; une revue de Sage en a rétracté un en 2020 à la demande des auteurs.",
  "Tribune de chercheurs et d'un journaliste scientifique, qui appellent à des rétractations.", 'secondaire'))
C_QI_RW_2024 = ('c_qi_rw_2024', src("Do some IQ data need a 'public health warning?' A paper based on a controversial psychologist's data is retracted", 'Adam Marcus, Retraction Watch', '18 mars 2024',
  'https://retractionwatch.com/2024/03/18/do-some-iq-data-need-a-public-health-warning-a-paper-based-on-a-controversial-psychologists-data-is-retracted/',
  "La revue Proceedings of the Royal Society B a rétracté en janvier 2024 un article de 2010 reliant la prévalence des parasites et la « distribution mondiale des capacités cognitives », fondé sur les données publiées en 2004 par Tatu Vanhanen et Richard Lynn (mort en 2023). Avis de rétractation : « the manifest problems in the data warranted retraction » ; les jeux de données « contain substantial inaccuracies and biases that throw substantial doubt on inferences made from them », problèmes non résolus dans les versions révisées.",
  "Site spécialisé dans le suivi des rétractations scientifiques.", 'secondaire'))
C_QI_RW_2025 = ('c_qi_rw_2025', src("Meet the researcher aiming to halt use of 'fundamentally flawed' database linking IQ and nationality", 'Dalmeet Singh Chawla, Retraction Watch', '25 novembre 2025',
  'https://retractionwatch.com/2025/11/25/meet-the-researcher-aiming-to-halt-use-of-fundamentally-flawed-database-linking-iq-and-nationality',
  "Rebecca Sear (Brunel University of London) a recensé 174 études utilisant la base de données des QI nationaux et contacté 18 revues : « There is absolutely no scientific merit whatsoever in the National IQ database ». Selon Jelte Wicherts, la mise à jour de David Becker « inherited many of the fundamental flaws ». Le 2 novembre 2025, la revue Cross-Cultural Research a rétracté une étude de 2023 utilisant ces données ; trois articles de Lynn ont fait l'objet d'avis de préoccupation (expressions of concern).",
  "Site spécialisé dans le suivi des rétractations scientifiques.", 'secondaire'))
C_QI_PIETSCHNIG_2015 = ('c_qi_pietschnig_2015', src("One Century of Global IQ Gains: A Formal Meta-Analysis of the Flynn Effect (1909-2013) — communiqué", 'Jakob Pietschnig et Martin Voracek (Université de Vienne), Perspectives on Psychological Science, vol. 10, p. 282-306 — communiqué EurekAlert', '1er juin 2015',
  'https://www.eurekalert.org/news-releases/490079',
  "Méta-analyse portant sur près de quatre millions de participants dans 31 pays entre 1909 et 2013 : les scores de QI ont augmenté d'environ trois points par décennie. Les gains ont été plus faibles en Europe pendant la Seconde Guerre mondiale et ralentissent depuis quelques décennies. Explications avancées : amélioration de la nutrition, de l'hygiène, des soins médicaux et de l'éducation. Selon les auteurs, « IQ gains thus appear to be hollow in terms of global cognitive ability changes ».",
  "Communiqué de presse universitaire sur un article évalué par les pairs.", 'etude'))
C_QI_RITCHIE_2018 = ('c_qi_ritchie_2018', src("How much does education improve intelligence? A meta-analysis", 'Stuart J. Ritchie (Université d’Édimbourg) et Elliot M. Tucker-Drob (Université du Texas), Psychological Science, vol. 29, n° 8, p. 1358-1369', '2018',
  'https://www.research.ed.ac.uk/en/publications/how-much-does-education-improve-intelligence-a-meta-analysis/',
  "Méta-analyse de 142 effets issus de 42 jeux de données (plus de 600 000 participants), fondée sur des méthodes quasi expérimentales (réformes de la scolarité obligatoire, dates limites d'entrée à l'école). Effet estimé : « approximately 1 to 5 IQ points for an additional year of education », durable tout au long de la vie.",
  "Article évalué par les pairs.", 'etude'))
C_QI_OMS_2002 = ('c_qi_oms_2002', src("Eliminating iodine deficiency disorders", 'Bruno de Benoist et Graeme Clugston (Organisation mondiale de la santé), Bulletin de l’OMS, vol. 80, n° 5', '2002',
  'https://scielosp.org/article/bwho/2002.v80n5/o2',
  "« Iodine-deficient communities have been found to score 10-15 points lower on IQ tests than iodine-replete ones. » La carence en iode est un problème de santé publique important dans 130 pays et touche 740 millions de personnes.",
  "Article de responsables de l'OMS ; données anciennes (2001-2002).", 'etude'))

FICHES.append(fiche(
 id='qi-pays-intelligence', affirmation="Les différences de QI entre pays prouvent que certains peuples sont moins intelligents.", volet='immigration', sous_theme='Racisme',
 mots_cles=['qi par pays', 'qi des africains', 'qi moyen pays', 'peuples moins intelligents', 'carte du qi', 'richard lynn', 'qi et race', 'qi national', 'intelligence des peuples'],
 verdict='contredit', fiabilite='interpretation',
 resume="Contredit. Les « QI nationaux » qui circulent viennent surtout des données de Richard Lynn, jugées gravement défaillantes par des chercheurs : échantillons minuscules (19 personnes pour l'Angola), aucun critère de sélection publié, études choisies selon leurs résultats. Des revues ont rétracté des articles fondés sur ces données en 2024 et 2025. Les scores de QI dépendent fortement de l'environnement : ils ont augmenté d'environ trois points par décennie au XXe siècle, une année d'école ajoute de 1 à 5 points, et la carence en iode en retire 10 à 15. Les écarts de scores mesurés ne prouvent aucune infériorité d'un peuple.",
 contexte="Des cartes du « QI moyen par pays » circulent sur les réseaux sociaux pour suggérer que certains peuples, notamment africains, seraient naturellement moins intelligents. Elles reprennent presque toujours les jeux de données de Richard Lynn, psychologue britannique mort en 2023.",
 explication="Il faut examiner la qualité des données utilisées, puis ce que la recherche sait des causes des écarts de scores : scolarisation, nutrition, santé, et l'évolution des scores dans le temps (effet Flynn).",
 sources=[C_QI_WICHERTS_2010, C_QI_STAT_2024, C_QI_RW_2024, C_QI_RW_2025, C_QI_PIETSCHNIG_2015, C_QI_RITCHIE_2018, C_QI_OMS_2002],
 faits=[
  fait("Une revue systématique publiée en 2010 trouve un QI moyen d'environ 82 (par rapport aux normes britanniques) pour les échantillons africains étudiés, là où Lynn et Vanhanen affirmaient qu'il était inférieur à 70 ; les auteurs demandent de lire ce chiffre à la lumière de l'effet Flynn.", 'c_qi_wicherts_2010', '2010', 'Afrique subsaharienne', "Avec des critères de sélection explicites, l'écart affiché par Lynn se réduit fortement.", 'etabli', '82'),
  fait("Fait défavorable : même avec une méthode rigoureuse, les scores moyens mesurés en Afrique subsaharienne restent inférieurs aux normes britanniques, d'environ 18 points selon cette revue de 2010.", 'c_qi_wicherts_2010', '2010', 'Afrique subsaharienne', "Les écarts de scores existent ; la question est ce qu'ils mesurent et d'où ils viennent.", 'etabli'),
  fait("Selon une tribune de chercheurs publiée par STAT, Lynn n'a publié aucun critère de sélection, et la moitié de ses estimations pour l'Afrique subsaharienne et l'Amérique latine reposent sur moins de 1 000 personnes, dont 19 pour l'Angola.", 'c_qi_stat_2024', '2024', 'Monde', "Un « QI national » calculé sur 19 personnes ne dit rien d'un pays de plusieurs dizaines de millions d'habitants.", 'interpretation', '19'),
  fait("Selon Retraction Watch, la revue de la Royal Society Proceedings B a rétracté en janvier 2024 un article de 2010 fondé sur les données de Lynn et Vanhanen, en jugeant que « les problèmes manifestes des données » justifiaient la rétractation.", 'c_qi_rw_2024', '2024', 'Monde', "Les revues scientifiques elles-mêmes reconnaissent que ces données ne sont pas fiables.", 'etabli'),
  fait("Selon Retraction Watch, la revue Cross-Cultural Research a rétracté en novembre 2025 une étude utilisant la base des QI nationaux ; une chercheuse a recensé 174 études qui l'utilisent encore.", 'c_qi_rw_2025', '2025', 'Monde', "Ces données défaillantes continuent d'alimenter des publications et des cartes diffusées en ligne.", 'etabli', '174'),
  fait("Selon une méta-analyse de l'université de Vienne portant sur près de quatre millions de personnes dans 31 pays, les scores de QI ont augmenté d'environ trois points par décennie entre 1909 et 2013, sans doute grâce à la nutrition, à l'hygiène, aux soins et à l'éducation.", 'c_qi_pietschnig_2015', '1909-2013', '31 pays', "Si les scores d'un même pays changent autant en un siècle, ils ne mesurent pas une capacité fixée par l'origine.", 'etabli', '3 points'),
  fait("Selon une méta-analyse portant sur plus de 600 000 personnes, une année d'éducation supplémentaire augmente le QI d'environ 1 à 5 points, de façon durable.", 'c_qi_ritchie_2018', '2018', 'Monde', "Les écarts de scolarisation entre pays suffisent à produire des écarts de QI importants.", 'etabli', '1 à 5 points'),
  fait("Selon l'OMS, les populations carencées en iode obtiennent des scores de QI de 10 à 15 points plus bas ; la carence touchait 740 millions de personnes dans 130 pays au début des années 2000.", 'c_qi_oms_2002', '2002', 'Monde', "La santé et la nutrition pèsent lourd sur les scores de QI.", 'etabli', '10 à 15 points'),
 ],
 court="Les « QI par pays » qui circulent viennent des données de Richard Lynn, jugées gravement défaillantes : 19 personnes testées pour toute l'Angola, aucun critère de sélection publié. Des revues ont rétracté des articles fondés sur ces données. Et les scores de QI dépendent de l'école, de la nutrition et de la santé : ils ont augmenté d'environ trois points par décennie au XXe siècle.",
 moyen="Les cartes du « QI par pays » reposent presque toutes sur les jeux de données du psychologue Richard Lynn. Des chercheurs ont montré qu'il n'avait publié aucun critère de sélection, qu'il retenait les échantillons africains aux scores bas et écartait les autres, et que certaines estimations reposaient sur quelques dizaines de personnes : 19 pour l'Angola. En 2024 et 2025, des revues scientifiques ont rétracté des articles fondés sur ces données.\n\nAvec une méthode rigoureuse, des chercheurs néerlandais trouvent bien des scores plus bas en Afrique subsaharienne, mais nettement moins qu'annoncé par Lynn. Et ces écarts s'expliquent par l'environnement : une année d'école ajoute de 1 à 5 points de QI, la carence en iode en retire 10 à 15, et les scores ont augmenté d'environ trois points par décennie dans les pays étudiés au XXe siècle. Nos arrière-grands-parents auraient eu des scores très inférieurs aux nôtres : personne n'en conclut qu'ils étaient un peuple inférieur.",
 detaille="L'affirmation repose sur des cartes du « QI moyen par pays » largement partagées en ligne. Presque toutes reprennent les données de Richard Lynn, psychologue britannique connu pour ses thèses racistes. Le problème commence avec ces données. Selon une tribune de chercheurs publiée en 2024, Lynn n'a jamais publié de critères de sélection, et la moitié de ses estimations pour l'Afrique subsaharienne et l'Amérique latine reposent sur moins de 1 000 personnes : 19 pour l'Angola. Une revue systématique de 2010 a montré qu'il avait retenu les échantillons africains aux scores bas et écarté les autres. En 2024, une revue de la Royal Society a rétracté un article fondé sur ces données, en raison de leurs « problèmes manifestes » ; une autre revue a fait de même en novembre 2025.\n\nIl faut être honnête : avec une méthode rigoureuse, les scores moyens mesurés en Afrique subsaharienne restent inférieurs aux normes britanniques, autour de 82 selon cette revue de 2010, contre moins de 70 chez Lynn. Mais un score de test n'est pas une capacité innée. Une méta-analyse portant sur plus de 600 000 personnes montre qu'une année d'école ajoute de 1 à 5 points. Selon l'OMS, les populations carencées en iode perdent 10 à 15 points. Les tests eux-mêmes ont été conçus en Occident, et leurs biais en Afrique restent mal connus.\n\nSurtout, les scores bougent vite. Entre 1909 et 2013, dans 31 pays, ils ont augmenté d'environ trois points par décennie, avec l'amélioration de la nutrition, de l'hygiène, des soins et de l'éducation : c'est l'effet Flynn. Avec les normes d'aujourd'hui, les Européens du début du XXe siècle auraient obtenu des scores très bas. Les écarts de QI entre pays mesurent donc surtout des écarts de conditions de vie, de santé et de scolarisation. Ils ne prouvent en rien qu'un peuple serait moins intelligent par nature.",
 empathie="Ces cartes ont l'air scientifiques, avec des chiffres précis pour chaque pays, et il est normal de se poser des questions en les voyant. Justement : regardons d'où viennent ces chiffres.",
 legitimes=["Les scores moyens aux tests de QI diffèrent réellement entre pays, même avec des données rigoureuses.", "Le QI est une mesure étudiée depuis longtemps, qui prédit en partie la réussite scolaire.", "Il est légitime de s'intéresser aux écarts de développement entre pays."],
 contre=[
  ("C'est de la science, ce sont des tests standardisés.", "Les données de Lynn n'ont aucun critère de sélection publié et reposent parfois sur quelques dizaines de personnes. Des revues scientifiques ont rétracté des articles qui les utilisaient."),
  ("Même avec de meilleures données, il y a un écart.", "Oui, mais une année d'école vaut de 1 à 5 points et la carence en iode en retire 10 à 15. Et les scores ont progressé d'environ trois points par décennie au XXe siècle : ils mesurent des conditions de vie, pas une nature."),
 ],
 questions=["Sais-tu sur combien de personnes repose le « QI national » de l'Angola dans ces cartes ?", "Si les scores ont augmenté d'environ trois points par décennie, nos arrière-grands-parents étaient-ils moins intelligents que nous ?", "Qu'est-ce qui pèse le plus sur un score de test : l'origine, ou l'école et la santé ?"],
 limites=["Les rétractations sont rapportées par Retraction Watch ; les avis de rétractation eux-mêmes n'ont pas été ouverts.", "La tribune publiée par STAT est un texte d'opinion de chercheurs qui demandent des rétractations ; ses chiffres proviennent en partie de l'étude de Wicherts et al. (2010).", "Les données de l'OMS sur l'iode datent de 2002.", "La méta-analyse sur l'effet Flynn a été lue à travers le communiqué de l'université de Vienne ; ses auteurs jugent que ces gains ne traduisent pas forcément une hausse de l'intelligence générale.", "Aucune source sur le paludisme n'a pu être lue ; la fiche n'en parle donc pas."],
 publics={'convaincus': "Ces cartes viennent des données de Richard Lynn, et le QI de l'Angola y repose sur 19 personnes testées. Des revues scientifiques ont retiré des articles fondés sur ces chiffres. Et les scores de QI ont augmenté d'environ trois points par décennie au XXe siècle : tes arrière-grands-parents n'étaient pas un peuple inférieur, ils allaient moins longtemps à l'école.",
  'indecis': "C'est normal de se poser des questions devant une carte pleine de chiffres. Mais ces chiffres viennent de données jugées gravement défaillantes, dont plusieurs revues ont tiré les conséquences. Les écarts de scores qui restent s'expliquent largement par l'école, la nutrition et la santé, qui peuvent faire varier le QI de plusieurs points."},
 a_actualiser='2027-06-30', raison="Suite de l'examen des articles de Lynn par Elsevier et éventuelles nouvelles rétractations.",
))



