FICHES.append(fiche(
 id='femmes-au-foyer', affirmation="Les femmes devraient rester à la maison pour élever leurs enfants.", volet='droits', sous_theme='Émancipation',
 mots_cles=['femmes au foyer', 'mere au foyer', 'femme a la maison', 'rester a la maison', 'tradwife', 'trad wife', 'role de la femme', 'les femmes doivent s occuper des enfants', 'retour au foyer'],
 verdict='opinion', fiabilite='interpretation',
 resume="C'est une opinion, mais elle a des conséquences qu'on peut mesurer. Aujourd'hui, 71,5 % des femmes de 15 à 64 ans sont actives. Celles qui s'arrêtent de travailler en paient le prix plus tard : après une séparation, leur niveau de vie chute bien plus que celui des hommes, plus d'un tiers des familles monoparentales sont pauvres, et les pensions des femmes restent inférieures de 38 % à celles des hommes. Quant aux enfants, la crèche favorise plutôt le langage, surtout dans les familles modestes. Chaque famille doit pouvoir choisir, mais une norme qui renvoie les femmes au foyer les rend dépendantes.",
 contexte="L'idée revient avec la mode des « tradwives », ces influenceuses qui mettent en scène la vie de femme au foyer soumise à son mari, et avec les discours masculinistes. Elle se présente souvent comme un « libre choix » ou comme l'intérêt des enfants.",
 explication="On ne peut pas trancher par des chiffres ce qu'une famille doit choisir. Mais on peut mesurer ce que l'arrêt de l'activité coûte aux femmes (pauvreté, séparation, retraite) et ce que disent les études sur le développement des enfants.",
 sources=[D_FF_INSEE_ACT, D_FF_INSEE_PAUV, D_FF_INSEE_SEP, D_FF_DREES_RET, D_FF_INED_CRECHE, D_FF_EURONEWS_TRAD],
 faits=[
  fait("En 2024, 71,5 % des femmes de 15 à 64 ans sont actives, contre 54,4 % en 1975 ; l'écart avec les hommes est passé de près de 30 points à 6 points.", 'd_ff_insee_act', '1975-2024', 'France', "Le travail des femmes est devenu la norme ; un retour au foyer irait à l'inverse de l'évolution de la société.", 'etabli', '71,5 %'),
  fait("En 2023, le taux de pauvreté des familles monoparentales atteint 34,3 %, contre 8,8 % pour les couples avec un ou deux enfants.", 'd_ff_insee_pauv', '2023', 'France', "Quand le couple se sépare, le parent qui élève seul les enfants, le plus souvent la mère, est très exposé à la pauvreté.", 'etabli', '34,3 %'),
  fait("En Occitanie, l'année d'une séparation, le niveau de vie médian des femmes baisse de 17 %, contre 7 % pour les hommes ; deux ans après, les femmes restent 9 % en dessous, les hommes ont presque tout récupéré.", 'd_ff_insee_sep', '2014-2020', 'Occitanie', "La dépendance financière au conjoint devient un piège en cas de rupture.", 'etabli', '17 %'),
  fait("Fin 2023, la pension de retraite moyenne de droit direct des femmes est inférieure de 38 % à celle des hommes ; l'écart était de 50 % en 2004.", 'd_ff_drees_ret', '2004-2023', 'France', "Les carrières interrompues pour élever les enfants se paient à la retraite ; l'écart se réduit à mesure que les femmes travaillent davantage.", 'etabli', '38 %'),
  fait("Selon une étude de l'Ined sur la cohorte Elfe, la crèche a un effet positif sur l'acquisition du langage, surtout pour les enfants de familles défavorisées.", 'd_ff_ined_creche', '2011 et années suivantes', 'France', "Garder les enfants à la maison n'est pas, en soi, meilleur pour leur développement.", 'etabli'),
  fait("Fait défavorable : selon la même étude, les enfants accueillis en crèche présentent en moyenne un peu plus de difficultés de comportement, un effet qui n'apparaît pas chez les enfants moins favorisés.", 'd_ff_ined_creche', '2011 et années suivantes', 'France', "La crèche n'a pas que des avantages ; les effets dépendent du milieu familial.", 'etabli'),
  fait("Selon une chercheuse citée par Euronews, le mouvement « tradwife » prône un retour aux normes de genre traditionnelles et peut servir de point d'entrée vers l'idéologie nationaliste blanche ; en France, ces comptes restent petits.", 'd_ff_euronews_trad', '2024', 'International et France', "La mode des femmes au foyer en ligne est aussi un outil idéologique.", 'interpretation'),
 ],
 court="Chacun organise sa famille comme il veut. Mais une femme qui arrête de travailler devient dépendante : en cas de séparation, son niveau de vie s'effondre, et à la retraite, les femmes touchent 38 % de moins. Et la crèche aide plutôt les enfants à parler.",
 moyen="Le choix de rester à la maison existe et se respecte. Mais en faire une règle pour toutes les femmes, c'est les rendre dépendantes. Aujourd'hui, plus de sept femmes sur dix sont actives.\n\nL'arrêt du travail coûte cher plus tard. Selon l'Insee, l'année d'une séparation, le niveau de vie des femmes baisse de 17 %, contre 7 % pour les hommes. Plus d'un tiers des familles monoparentales sont pauvres. À la retraite, les pensions des femmes restent inférieures de 38 %. Côté enfants, une étude de l'Ined montre que la crèche favorise le langage, surtout dans les familles modestes.",
 detaille="Il n'y a pas de bonne réponse chiffrée à la question de savoir qui doit élever les enfants : c'est une affaire de valeurs et de choix familiaux. Mais il faut regarder ce que produit, concrètement, l'arrêt de l'activité des femmes.\n\nD'abord, la société a changé : 71,5 % des femmes de 15 à 64 ans sont actives en 2024, contre 54,4 % en 1975. Ensuite, la dépendance financière se paie cher en cas de séparation. En Occitanie, l'Insee mesure que le niveau de vie des femmes baisse de 17 % l'année de la rupture, et de 21 % pour celles qui ont les enfants à charge, contre 7 % pour les hommes. Au niveau national, 34,3 % des familles monoparentales vivent sous le seuil de pauvreté.\n\nLa facture arrive aussi à la retraite : la pension moyenne des femmes reste inférieure de 38 % à celle des hommes, même si l'écart se réduit à mesure qu'elles travaillent davantage.\n\nPour les enfants, l'argument ne tient pas mieux. Selon l'Ined, la crèche améliore l'acquisition du langage, surtout chez les enfants de familles défavorisées, avec un effet un peu négatif sur certains comportements chez les enfants plus favorisés. Ce qui compte, c'est un vrai choix : des places de crèche, un congé parental bien payé et partagé entre les deux parents.",
 empathie="Beaucoup de parents souffrent de ne pas voir assez leurs enfants, et le rythme travail-crèche-maison peut être épuisant. Vouloir plus de temps en famille est légitime.",
 legitimes=["Certaines femmes et certains hommes choisissent sincèrement de rester à la maison, et ce choix mérite le respect.", "Les journées très longues en crèche peuvent fatiguer les jeunes enfants.", "Les parents manquent souvent de temps avec leurs enfants."],
 contre=[
  ("Avant, les femmes restaient à la maison et les enfants étaient mieux élevés.", "Avant, les femmes n'avaient souvent ni revenus propres ni moyen de quitter un mari violent. Et les études récentes montrent que la crèche aide le langage des enfants, surtout dans les familles modestes."),
  ("C'est un libre choix, le féminisme devrait le respecter.", "Le choix individuel se respecte. Le problème, c'est d'en faire une règle pour toutes les femmes, et de laisser celles qui s'arrêtent sans protection en cas de séparation ou à la retraite."),
 ],
 questions=["Et si le couple se sépare, de quoi vit la femme qui a arrêté de travailler pendant dix ans ?", "Pourquoi ce serait forcément la mère, et pas le père, qui resterait à la maison ?"],
 limites=["L'étude sur la séparation porte sur l'Occitanie, pas sur toute la France.", "L'étude de l'Ined porte sur des enfants nés en 2011 et sur leurs premières années.", "La place réelle du mouvement « tradwife » en France est mal mesurée ; la source est un reportage citant une chercheuse.", "La question de fond relève des valeurs : les chiffres éclairent les conséquences, ils ne tranchent pas le choix."],
 publics={'convaincus': "Chacun fait ce qu'il veut chez soi. Mais imagine ta fille qui arrête de travailler dix ans et dont le couple se sépare : selon l'Insee, le niveau de vie des femmes chute de 17 % l'année de la rupture, et plus d'un tiers des mères seules sont pauvres. Être au foyer sans revenus, c'est être à la merci de son conjoint.",
  'indecis': "Vouloir passer plus de temps avec ses enfants, c'est légitime. Mais quand les femmes arrêtent de travailler, elles le paient en cas de séparation et à la retraite, avec des pensions inférieures de 38 %. Et la crèche n'abîme pas les enfants : elle aide même leur langage. Le vrai choix, ce sont des places de crèche et un congé parental bien payé pour les deux parents."},
 a_actualiser='2027-06-30', raison="Nouvelles données de l'Insee sur l'activité et la pauvreté, et panorama annuel des retraites de la DREES.",
))

# 3 ── « Les jeunes hommes votent à l'extrême droite à cause du féminisme » ──
D_JH_IPSOS_LEG = ('d_jh_ipsos_leg', src("Sociologie des électorats — Législatives 2024 (1er tour)", 'Ipsos Talan pour France Télévisions, Radio France et Public Sénat (sondage le jour du vote)', '30 juin 2024',
  'https://www.ipsos.com/fr-fr/legislatives-2024/node/1025896',
  "Enquête du 27 au 28 juin 2024 auprès de 10 286 inscrits. Par rapport à 2022, le RN progresse chez « les femmes (de 17% à 32%) » et chez « les moins de 35 ans (de 18% à 32%) ». Chez les 18-24 ans, le NFP devance le RN de 15 points ; la moitié des moins de 25 ans a choisi le NFP.",
  "Sondage d'un institut privé, réalisé pour des médias publics.", 'secondaire'))
