FICHES.append(fiche(
 id='jeunes-hommes-extreme-droite-feminisme', affirmation="Les jeunes hommes votent à l'extrême droite à cause du féminisme.", volet='politique', sous_theme='Droite et extrême droite',
 mots_cles=['jeunes hommes extreme droite', 'jeunes hommes votent rn', 'vote des jeunes hommes', 'feminisme vote rn', 'fosse jeunes hommes jeunes femmes', 'jeunes hommes masculinisme', 'gender gap vote', 'les jeunes votent bardella'],
 verdict='trompeur', fiabilite='debat',
 resume="Trompeur, car trop simple. Il existe bien un écart grandissant entre jeunes femmes et jeunes hommes : ces derniers se placent plus souvent à droite radicale et adhèrent davantage aux stéréotypes de genre, sur fond de montée du masculinisme. Mais aucune étude ne démontre que le féminisme serait la cause de leur vote. Le vote RN des jeunes s'explique d'abord par le pouvoir d'achat, l'immigration et le niveau de diplôme. Et les femmes votent presque autant RN que les hommes : 32 % contre 36 % aux législatives de 2024.",
 contexte="Depuis les élections de 2024, de nombreux commentaires expliquent la poussée du RN chez les jeunes par un rejet masculin du féminisme et de #MeToo. Cette lecture circule aussi bien à droite, pour accuser le féminisme, qu'à gauche, pour dénoncer le masculinisme.",
 explication="Il faut regarder les sondages de sortie des urnes par âge et par sexe, les enquêtes sur les valeurs des jeunes et les motivations de vote déclarées, en distinguant une corrélation d'une cause.",
 sources=[D_JH_IPSOS_LEG, D_JH_PUBSENAT, D_JH_CEPREMAP, D_JH_HCE_2025, D_JH_HCE_2026, D_JH_FJJ_2024, D_JH_TNJ_2026],
 faits=[
  fait("Selon Ipsos, au premier tour des législatives de 2024, le RN a obtenu 36 % chez les hommes et 32 % chez les femmes, un écart faible.", 'd_jh_pubsenat', '2024', 'France', "Le vote RN n'est pas une affaire d'hommes : les femmes le choisissent presque autant.", 'estimation', '32 %'),
  fait("Selon Ipsos, le vote RN est passé de 17 % à 32 % chez les femmes et de 18 % à 32 % chez les moins de 35 ans entre 2022 et 2024.", 'd_jh_ipsos_leg', '2022-2024', 'France', "La poussée du RN touche aussi les femmes, ce que l'explication par le seul rejet masculin du féminisme ne permet pas de comprendre.", 'estimation', '32 %'),
  fait("Selon Ipsos, chez les 18-24 ans, le Nouveau Front populaire est arrivé en tête en 2024, avec 15 points d'avance sur le RN.", 'd_jh_ipsos_leg', '2024', 'France', "La jeunesse vote d'abord à gauche ; le RN y reste minoritaire.", 'estimation'),
  fait("Fait défavorable : selon une note du Cepremap fondée sur l'European Social Survey, 14 % des hommes de moins de 40 ans se placent à la droite radicale en 2023 (+7 points), contre 7 % des femmes, une proportion stable.", 'd_jh_cepremap', '2002-2023', 'France', "Un vrai fossé politique se creuse entre jeunes hommes et jeunes femmes.", 'estimation', '14 %'),
  fait("Fait défavorable : selon le Haut Conseil à l'égalité, 45 % des hommes de moins de 35 ans jugent difficile d'être un homme, une proportion en forte hausse chez les 15-24 ans.", 'd_jh_hce_2025', '2024', 'France', "Une partie des jeunes hommes vit les changements liés à l'égalité comme une perte, terrain sur lequel prospère le masculinisme.", 'estimation', '45 %'),
  fait("Selon le Haut Conseil à l'égalité, le masculinisme est devenu « un système idéologique structuré », et l'écart d'opinions entre femmes et hommes est le plus élevé chez les jeunes.", 'd_jh_hce_2026', '2025', 'France', "Le masculinisme est un mouvement organisé qui travaille ce malaise ; ce n'est pas le féminisme qui pousse mécaniquement au vote RN.", 'interpretation'),
  fait("Selon une analyse publiée par la Fondation Jean-Jaurès, le pouvoir d'achat est la première motivation de vote des jeunes en 2024, l'immigration la troisième ; seuls 40 % des 18-24 ans ont voté aux européennes.", 'd_jh_fjj_2024', '2024', 'France', "Les motivations déclarées des jeunes électeurs sont d'abord économiques et migratoires.", 'estimation', '40 %'),
  fait("Selon une analyse de Terra Nova Jeunes, le vote RN des jeunes est « fortement corrélé au niveau de diplôme », et les 33 % de jeunes votants RN aux législatives de 2024 représentent moins de 10 % de la classe d'âge.", 'd_jh_tnj_2026', '2024', 'France', "Le vote RN des jeunes tient beaucoup à leur situation sociale, et il reste minoritaire dans la jeunesse.", 'interpretation', '10 %'),
 ],
 court="Il y a bien un fossé entre jeunes femmes et jeunes hommes, et le masculinisme progresse. Mais rien ne prouve que le féminisme fasse voter RN. Les jeunes citent d'abord le pouvoir d'achat, et les femmes votent presque autant RN que les hommes.",
 moyen="L'écart existe : selon une note du Cepremap, 14 % des hommes de moins de 40 ans se placent à la droite radicale, contre 7 % des femmes. Et le Haut Conseil à l'égalité constate un masculinisme en pleine expansion chez les jeunes.\n\nMais dire que le féminisme serait la cause du vote RN ne tient pas. Les femmes ont voté RN presque autant que les hommes en 2024 (32 % contre 36 % selon Ipsos), et chez les 18-24 ans, c'est la gauche qui arrive en tête. Les jeunes qui votent RN citent d'abord le pouvoir d'achat et l'immigration, et ce vote est très lié au niveau de diplôme.",
 detaille="Il y a un fond de vérité. Les enquêtes montrent un fossé croissant entre jeunes femmes et jeunes hommes. Selon une note du Cepremap, 14 % des hommes de moins de 40 ans se placent à la droite radicale en 2023, contre 7 % des femmes. Selon le Haut Conseil à l'égalité, 45 % des hommes de moins de 35 ans jugent difficile d'être un homme, et le masculinisme est devenu un mouvement idéologique structuré, très présent sur les réseaux sociaux.\n\nMais il y a loin de cette corrélation à une cause. Le vote RN progresse autant chez les femmes : de 17 % à 32 % entre 2022 et 2024 selon Ipsos, presque autant que chez les hommes. Si le rejet du féminisme expliquait tout, le vote RN n'aurait pas autant progressé chez les femmes.\n\nLes jeunes qui votent RN mettent d'abord en avant le pouvoir d'achat, puis l'immigration. Leur vote est très lié au niveau de diplôme et à la précarité. Enfin, la majorité des jeunes ne vote pas, et parmi ceux qui votent, la gauche arrive en tête chez les 18-24 ans.\n\nLe vrai sujet, c'est que des influenceurs masculinistes exploitent le malaise de jeunes hommes précaires. Accuser le féminisme revient à reprendre leur discours.",
 empathie="Beaucoup de parents s'inquiètent de voir leurs fils se radicaliser en ligne, et beaucoup de jeunes hommes se sentent sans repères. Ces inquiétudes sont réelles.",
 legitimes=["Les enquêtes montrent bien un écart grandissant entre les opinions des jeunes femmes et des jeunes hommes.", "Le masculinisme progresse sur les réseaux sociaux, et il vise les jeunes hommes.", "Une partie des jeunes hommes se sent délaissée par les discours politiques."],
 contre=[
  ("Si les jeunes femmes votent à gauche et les jeunes hommes à droite, c'est bien à cause du féminisme.", "Les femmes votent presque autant RN que les hommes en 2024. Et les jeunes qui votent RN citent d'abord le pouvoir d'achat. Le féminisme n'explique pas cela."),
  ("Le féminisme a dévalorisé les hommes, il ne faut pas s'étonner du résultat.", "Ce discours est celui des influenceurs masculinistes. L'égalité ne retire rien aux hommes ; c'est la précarité et l'absence d'avenir qui nourrissent la colère."),
 ],
 questions=["Si c'était le féminisme, pourquoi les femmes votent-elles presque autant RN que les hommes ?", "Qu'est-ce qui pèse le plus dans la vie d'un jeune de vingt ans : le féminisme ou le prix du loyer ?"],
 limites=["Aucun sondage lu ne publie de croisement âge × sexe pour le vote RN de 2024 ; les chiffres par sexe portent sur tous les âges.", "Les sondages le jour du vote ont des marges d'erreur, surtout sur les petits sous-groupes.", "La note du Cepremap porte sur l'autopositionnement politique, pas sur le vote ; elle mentionne par ailleurs des « législatives de 2023 », probablement une erreur de date, chiffre non repris.", "Les causes du vote sont débattues entre chercheurs : il n'existe pas d'étude démontrant un lien de cause à effet."],
 publics={'convaincus': "Si le féminisme faisait voter RN, les femmes ne voteraient pas RN. Or, selon Ipsos, elles l'ont fait à 32 % en 2024, presque autant que les hommes. Les jeunes qui votent RN parlent d'abord de fin de mois et d'immigration, pas de féminisme.",
  'indecis': "C'est vrai qu'un fossé se creuse entre jeunes femmes et jeunes hommes, et que le masculinisme gagne du terrain en ligne. Mais rien ne prouve que le féminisme fasse voter RN : les jeunes citent d'abord le pouvoir d'achat, et leur vote dépend beaucoup de leur diplôme et de leur précarité. Accuser le féminisme, c'est reprendre le discours des influenceurs masculinistes."},
 a_actualiser='2027-06-30', raison="Sondages de sortie des urnes de la présidentielle 2027 et prochain rapport du HCE.",
))

# 4 ── « Des drag-queens lisent des contes aux enfants pour les endoctriner » ──
D_DQ_ISD_2024 = ('d_dq_isd_2024', src("A Year of Hate: Anti-Drag Mobilisation Efforts Targeting LGBTQ+ People in France", 'Institute for Strategic Dialogue (ISD, institut de recherche sur l’extrémisme et la désinformation)', '2024',
  'https://www.isdglobal.org/wp-content/uploads/2024/07/A-Year-of-Hate_Anti_Drag-Mobilisation_France.pdf',
  "Analyse de cinq mobilisations contre des événements drag entre décembre 2022 et mai 2023 : Bordeaux (11/12/22), Lamballe-Armor (16/01/23), Toulouse (18/02/23), Paris (11/03/23), Saint-Senoux (13/05/23). Acteurs : groupes d'extrême droite (dont L'Oriflamme Rennes, La Furie française), sites d'extrême droite, Reconquête ; le RN a distribué des tracts avant l'événement de Saint-Senoux ; aussi des groupes « anti-genre ». Récits : « protecting the children », accusations de « child grooming ». À Bordeaux, l'artiste a reçu un « surge of abusive messages and death threats ». L'événement de Toulouse a été annulé par les artistes après que le maire a demandé de le réserver aux adultes ; ceux de Lamballe, Paris et Saint-Senoux ont eu lieu.",
  "Rapport d'un institut indépendant spécialisé dans l'extrémisme en ligne (en anglais).", 'etude'))
D_DQ_LIVRESHEBDO = ('d_dq_livreshebdo', src("Bretagne : une lecture jeunesse par des drag-queens suscite le débat", 'Livres Hebdo (presse professionnelle du livre)', '17 janvier 2023',
  'https://www.livreshebdo.fr/article/bretagne-une-lecture-jeunesse-par-des-drag-queens-suscite-le-debat',
  "À la bibliothèque de Lamballe (Côtes-d'Armor), une compagnie drag de Rennes est invitée pour une lecture de contes suivie d'un atelier maquillage, spectacle « Uniques en son genre », ouvert aux enfants à partir de 3 ans. Une pétition d'un mouvement catholique (VIA, la voix du peuple) réunit près de 9 000 signatures. L'adjoint à la culture refuse d'annuler. Le directeur de la compagnie précise que l'atelier ne consiste pas à transformer un enfant en drag-queen et dit : « Rien de malintentionné ».",
  "Presse professionnelle du livre.", 'secondaire'))
D_DQ_RTBF = ('d_dq_rtbf', src("Face aux attaques, les Drag Queens et Kings continuent de lire des contes pour les enfants", 'Maxime Maillet, RTBF (radio-télévision publique belge)', '27 mars 2023',
  'https://www.rtbf.be/article/face-aux-attaques-les-drag-queens-et-kings-continuent-de-lire-des-contes-pour-les-enfants-11170911',
  "Le projet belge « Unique en Son Genre » organise une centaine de lectures par saison (bibliothèques, centres culturels, écoles). Les artistes « content des histoires » et répondent aux questions. Le coordinateur : « nous ne parlons jamais de sexualité avec des enfants » ; si les opposants venaient, « ils verraient qu'il n'y a vraiment aucun souci ». En février 2023, à La Louvière, neuf opposants ont collé sur les vitres d'une bibliothèque des slogans violents évoquant la pédophilie. En France, à Toulouse, un atelier a été réorienté vers un public adulte.",
  "Service public audiovisuel belge.", 'secondaire'))
D_DQ_AN_8542 = ('d_dq_an_8542', src("Question écrite n° 8542 (16e législature)", 'Assemblée nationale (question de Sophie Taillé-Polian, députée écologiste, NUPES)', '6 juin 2023',
  'https://www.assemblee-nationale.fr/dyn/16/questions/QANR5L16QE8542.pdf',
  "La députée évoque un atelier de lecture de drag-queens à Saint-Senoux où « une vingtaine de militants fascistes ont intimidé physiquement les participants ». Pas de réponse du Gouvernement ; question retirée le 11 juin 2024 en fin de mandat.",
  "Question parlementaire : point de vue d'une élue de gauche, sans réponse ministérielle.", 'primaire'))
D_DQ_ACTUALITTE = ('d_dq_actualitte', src("Après des lectures par des drag-queens, une bibliothèque parisienne menacée", 'Camille Cado, ActuaLitté', '20 mars 2019',
  'https://actualitte.com/article/14243/reseaux-sociaux/apres-des-lectures-par-des-drag-queens-une-bibliotheque-parisienne-menacee',
  "Bibliothèque Louise-Michel (Paris 20e), 16 mars 2019 : atelier de lecture de contes pour enfants par des drag-queens, avec des contes non genrés (dont Boucle d'Or et les trois ours revisité). Objectif, selon la bibliothèque : interroger les stéréotypes sur le rôle des filles et des garçons. Plus de 400 messages de haine en quelques jours ; un membre du personnel dénonce une « vague de harcèlement sans précédent ».",
  "Média spécialisé dans le livre.", 'secondaire'))

FICHES.append(fiche(
 id='drag-queens-enfants', affirmation="Des drag-queens lisent des contes aux enfants pour les endoctriner.", volet='droits', sous_theme='Droits des personnes LGBT',
 mots_cles=['drag queen enfants', 'drag queens contes', 'lecture drag queen', 'drag queen bibliotheque', 'drag queens endoctrinement', 'heure du conte drag', 'saint senoux', 'lamballe drag', 'propagande lgbt enfants'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Des lectures de contes par des artistes drag existent bien, dans quelques bibliothèques et festivals, et elles portent un message assumé : questionner les stéréotypes de genre et apprendre la tolérance. Mais on n'y parle pas de sexualité, les parents choisissent d'y emmener leurs enfants, et aucune source ne montre d'« endoctrinement ». Ce qui est documenté, en revanche, ce sont les actions de groupes d'extrême droite contre ces lectures en 2023 : pétitions, menaces de mort, intimidations à Saint-Senoux.",
 contexte="Venue des États-Unis, la polémique sur les « drag queen story hours » a gagné la France fin 2022 et en 2023, avec des mobilisations à Bordeaux, Lamballe, Toulouse, Paris et Saint-Senoux. Les opposants parlent d'« endoctrinement » ou de « protection de l'enfance ».",
 explication="Il faut regarder ce qui se passe pendant ces lectures (public, contenu, déroulé), qui les organise et qui s'y oppose, et chercher s'il existe des preuves d'un tort fait aux enfants.",
 sources=[D_DQ_ISD_2024, D_DQ_LIVRESHEBDO, D_DQ_RTBF, D_DQ_AN_8542, D_DQ_ACTUALITTE],
 faits=[
  fait("Selon l'Institute for Strategic Dialogue, cinq mobilisations contre des événements drag ont eu lieu en France entre décembre 2022 et mai 2023 : Bordeaux, Lamballe-Armor, Toulouse, Paris et Saint-Senoux.", 'd_dq_isd_2024', '2022-2023', 'France', "Le phénomène est limité : quelques lectures, devenues des cibles nationales.", 'estimation', '5'),
  fait("Selon le même rapport, ces mobilisations ont été menées par des groupes d'extrême droite et des militants anti-genre, autour des récits de « protection des enfants » et d'accusations de « grooming ».", 'd_dq_isd_2024', '2022-2023', 'France', "L'accusation d'endoctrinement fait partie d'une campagne politique organisée.", 'interpretation'),
  fait("D'après Livres Hebdo, la lecture de Lamballe en janvier 2023 consistait en des contes suivis d'un atelier maquillage pour enfants à partir de 3 ans ; la compagnie a précisé qu'il ne s'agissait pas de transformer les enfants en drag-queens.", 'd_dq_livreshebdo', '2023', 'Lamballe-Armor', "Concrètement, ce sont des contes lus par des artistes déguisés, comme d'autres spectacles pour enfants.", 'interpretation'),
  fait("Selon la RTBF, les responsables d'un projet belge qui organise une centaine de lectures par saison affirment : « nous ne parlons jamais de sexualité avec des enfants ».", 'd_dq_rtbf', '2023', 'Belgique', "Le contenu de ces lectures n'a rien de sexuel.", 'interpretation'),
  fait("Selon une question écrite de la députée Sophie Taillé-Polian, à Saint-Senoux, une vingtaine de militants ont intimidé physiquement les participants d'un atelier de lecture de drag-queens en mai 2023.", 'd_dq_an_8542', '2023', 'Saint-Senoux (Ille-et-Vilaine)', "Les violences documentées viennent des opposants, pas des lectures.", 'interpretation'),
  fait("Selon l'ISD, l'artiste visé à Bordeaux a reçu une vague de messages haineux et de menaces de mort, et la lecture de Toulouse a été annulée après que le maire a demandé qu'elle soit réservée aux adultes.", 'd_dq_isd_2024', '2022-2023', 'Bordeaux, Toulouse', "La pression des opposants a parfois réussi à faire annuler des événements culturels.", 'interpretation'),
  fait("Fait défavorable : d'après ActuaLitté, la bibliothèque parisienne qui a organisé une lecture en 2019 voulait, selon ses mots, interroger les stéréotypes sur le rôle des filles et des garçons.", 'd_dq_actualitte', '2019', 'Paris', "Ces lectures portent bien un message éducatif sur l'égalité et la tolérance ; on peut en débattre, mais transmettre des valeurs n'est pas endoctriner.", 'interpretation'),
 ],
 court="Ces lectures existent, mais ce sont des contes pour enfants, sans sexualité, auxquels les parents choisissent d'aller. Elles parlent de tolérance et de stéréotypes. Ce qui est documenté, ce sont les menaces et intimidations de groupes d'extrême droite contre elles.",
 moyen="Quelques bibliothèques ont invité des artistes drag à lire des contes, comme à Lamballe ou à Paris. On y lit des histoires, parfois suivies d'un atelier maquillage, et les organisateurs disent ne jamais parler de sexualité. Le message est assumé : apprendre aux enfants que filles et garçons peuvent sortir des stéréotypes.\n\nAucune source ne montre d'endoctrinement ou de tort fait aux enfants. En revanche, selon un institut spécialisé dans l'extrémisme, ces lectures ont été visées en 2023 par des groupes d'extrême droite : pétitions, menaces de mort à Bordeaux, intimidation des participants à Saint-Senoux.",
 detaille="L'affirmation part d'un fait réel : des artistes drag lisent parfois des contes aux enfants. En France, cela concerne quelques bibliothèques ou festivals. À Lamballe, en janvier 2023, il s'agissait de contes suivis d'un atelier maquillage pour les enfants à partir de 3 ans ; la compagnie a précisé qu'elle ne transformait pas les enfants en drag-queens. En Belgique, les organisateurs d'une centaine de lectures par saison affirment ne jamais parler de sexualité avec les enfants.\n\nCes lectures ont un objectif assumé : interroger les stéréotypes sur le rôle des filles et des garçons, et apprendre la tolérance. On peut ne pas partager ce choix éducatif. Mais les parents sont libres d'y aller ou non, et aucune source ne montre un tort fait aux enfants. L'école et les livres jeunesse transmettent aussi des valeurs ; ce n'est pas de l'endoctrinement.\n\nCe qui est documenté, ce sont les mobilisations contre ces lectures. L'Institute for Strategic Dialogue en a recensé cinq en France entre décembre 2022 et mai 2023, portées par des groupes d'extrême droite et des militants anti-genre, avec des accusations de pédophilie. À Bordeaux, l'artiste a reçu des menaces de mort. À Saint-Senoux, une vingtaine de militants ont intimidé les participants. À Toulouse, la lecture a été annulée. L'accusation d'endoctrinement sert surtout à rendre suspectes les personnes LGBT.",
 empathie="Les parents veulent protéger leurs enfants et choisir les valeurs qu'on leur transmet. Il est normal de se poser des questions sur un spectacle qu'on ne connaît pas.",
 legitimes=["Les parents doivent pouvoir savoir ce qui est proposé à leurs enfants et choisir d'y aller ou non.", "Ces lectures portent bien un message sur les stéréotypes de genre.", "Il est légitime de demander que les spectacles pour enfants soient adaptés à leur âge."],
 contre=[
  ("On n'a pas à montrer des hommes déguisés en femmes à des enfants de 3 ans.", "Le déguisement fait partie de tous les spectacles pour enfants, du clown au Père Noël. Les parents choisissent d'y aller, et les organisateurs ne parlent jamais de sexualité."),
  ("C'est de la propagande LGBT.", "Apprendre aux enfants à respecter les gens différents, ce n'est pas de la propagande. Ce qui ressemble à une campagne organisée, ce sont plutôt les pétitions, menaces et intimidations de groupes d'extrême droite."),
 ],
 questions=["As-tu vu ce qui se passe réellement pendant une de ces lectures ?", "Qu'est-ce qui choque le plus : un conte lu par un artiste maquillé, ou des militants qui viennent intimider des parents et des enfants ?"],
 limites=["Le rapport de l'ISD couvre la période de décembre 2022 à mai 2023 et ne donne pas de bilan plus récent.", "Le déroulé détaillé des lectures françaises n'est décrit que par la presse et par les organisateurs ; aucun contrôle indépendant n'a été lu.", "La suite judiciaire de l'affaire de Saint-Senoux n'a pas pu être vérifiée dans une source ouverte ; elle n'est pas citée.", "Les témoignages belges ne concernent pas directement la France."],
 publics={'convaincus': "Tu as vu une de ces lectures ? Ce sont des contes, parfois avec un atelier maquillage, auxquels les parents choisissent d'emmener leurs enfants, et les organisateurs ne parlent jamais de sexualité. Le seul moment où il y a eu de la violence, c'est quand des militants sont venus intimider les familles à Saint-Senoux.",
  'indecis': "C'est normal de vouloir savoir ce qu'on montre aux enfants. Ces lectures existent, mais elles sont rares, facultatives, et parlent surtout de tolérance et de stéréotypes. Aucune source ne montre un tort fait aux enfants ; ce qui est documenté, ce sont des campagnes d'extrême droite contre ces lectures."},
 a_actualiser='2027-06-30', raison="Nouveaux rapports sur les mobilisations anti-LGBT et bilan annuel des actes anti-LGBT.",
))

# 5 ── « CNews est la première chaîne d'info, la preuve que les Français pensent comme elle » ──
