FICHES.append(fiche(
 id='ukraine-negocier-poutine', affirmation="Il faut négocier avec Poutine, c'est Zelensky qui empêche la paix.", volet='international', sous_theme='Guerres et conflits',
 mots_cles=['negocier avec poutine', 'zelensky empeche la paix', 'paix en ukraine', 'negociations ukraine russie', 'cessez le feu ukraine', 'accord d istanbul', 'plan de paix trump', 'abou dhabi ukraine', 'ceder le donbass'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Des négociations ont bien lieu : à Istanbul en 2022, puis en 2025, et à Abou Dhabi en 2026 avec une médiation américaine. En mars 2025, l'Ukraine a accepté un cessez-le-feu de 30 jours proposé par Washington, à condition que la Russie l'applique aussi ; Moscou a posé des conditions. Les exigences russes, réaffirmées en juin 2025 et encore en novembre 2026, incluent le retrait ukrainien de quatre régions que la Russie ne contrôle même pas entièrement, la neutralité et un plafond pour l'armée ukrainienne. Il est vrai que Kiev refuse aussi de céder du territoire et qu'un décret de 2022 déclare « impossible » de négocier avec Poutine. Mais faire porter à Zelensky seul l'absence de paix efface le rôle de l'agresseur.",
 contexte="Depuis l'invasion à grande échelle de février 2022, une partie de l'opinion estime que la paix serait possible si l'Ukraine acceptait de négocier, et accuse Volodymyr Zelensky de la bloquer. Les négociations ont repris à Abou Dhabi en novembre 2026.",
 explication="Il faut reprendre la chronologie des négociations depuis 2022, en datant chaque étape, et comparer ce que chaque camp a accepté ou refusé, notamment sur le cessez-le-feu et les territoires.",
 sources=[E_UKR_NPR_2024, E_UKR_EURONEWS_2026, E_UKR_JAMESTOWN_2022, E_UKR_JEDDAH_2025, E_UKR_PS_2025, E_UKR_PISM_2025, E_UKR_OSW_2025, E_UKR_GC_2025, E_UKR_AJ_2025, E_UKR_ONU_2026, E_UKR_AP_2026],
 faits=[
  fait("Selon les chercheurs Samuel Charap et Sergey Radchenko, lors des pourparlers d'Istanbul au printemps 2022, l'Ukraine était prête à une neutralité permanente en échange de garanties de sécurité, mais les deux camps restaient très éloignés sur la démilitarisation et l'Ukraine a refusé des exigences russes ajoutées tardivement.", 'e_ukr_npr_2024', '2022', 'Ukraine, Russie', "Kiev a négocié et fait des concessions importantes dès 2022 ; l'accord n'était pas prêt à être signé.", 'interpretation'),
  fait("Selon les mêmes chercheurs, l'échec de 2022 tient au repli russe devant Kiev, à l'indignation après Boutcha et à des garanties occidentales jamais vraiment discutées ; Sergey Radchenko ajoute : « we do not know whether Putin was negotiating in good faith ».", 'e_ukr_npr_2024', '2022', 'Ukraine, Russie', "L'échec a plusieurs causes, et rien ne prouve que la Russie était prête à une paix acceptable.", 'interpretation'),
  fait("Fait défavorable : un décret du 4 octobre 2022 a entériné la décision du Conseil de sécurité ukrainien jugeant « impossible » de négocier avec Vladimir Poutine, prise le jour même où la Russie annonçait l'annexion de quatre régions ; il n'interdit pas les négociations techniques, selon la Jamestown Foundation.", 'e_ukr_jamestown_2022', '2022', 'Ukraine', "Kiev a bien fermé la porte à Poutine pendant un temps, en réaction à l'annexion ; elle a depuis repris des pourparlers directs.", 'etabli'),
  fait("Le 11 mars 2025 à Djeddah, l'Ukraine s'est dite prête à accepter « an immediate, interim 30-day ceasefire » proposé par les États-Unis, sous réserve de son acceptation et de son application simultanée par la Russie, selon la déclaration commune publiée par Kiev.", 'e_ukr_jeddah_2025', '2025', 'Ukraine, États-Unis', "Sur le cessez-le-feu, c'est Kiev qui a dit oui la première.", 'etabli'),
  fait("Selon l'institut polonais PISM, Moscou a rejeté en mars 2025 le principe d'un cessez-le-feu préalable aux négociations et exigé la suspension de l'aide militaire et du renseignement occidentaux à l'Ukraine.", 'e_ukr_pism_2025', '2025', 'Russie', "La Russie a refusé la trêve sans conditions que l'Ukraine avait acceptée.", 'interpretation'),
  fait("Selon le mémorandum russe remis à Istanbul le 2 juin 2025, Moscou exige la reconnaissance juridique internationale de l'intégration de la Crimée, de Donetsk, de Louhansk, de Zaporijia et de Kherson, le retrait complet des forces ukrainiennes de ces régions et la neutralité de l'Ukraine.", 'e_ukr_gc_2025', '2025', 'Russie, Ukraine', "La Russie demande à l'Ukraine de livrer des territoires que l'armée russe n'a pas conquis.", 'etabli'),
  fait("Fait défavorable : selon l'Associated Press, en novembre 2026, Volodymyr Zelensky refuse toujours de céder volontairement du territoire et rejette toute limite sur son armée ou ses partenariats occidentaux.", 'e_ukr_ap_2026', '2026', 'Ukraine', "Kiev aussi a des lignes rouges, ce qui bloque un accord ; mais il s'agit de son propre territoire et de sa capacité à se défendre.", 'etabli'),
  fait("Selon l'Associated Press, lors des pourparlers d'Abou Dhabi du 10 novembre 2026, les premiers entre Russes, Ukrainiens et Américains depuis neuf mois, Moscou exigeait encore le retrait ukrainien de quatre régions jamais entièrement conquises et refusait un cessez-le-feu général, tandis que Kiev demandait un cessez-le-feu immédiat et une rencontre entre les deux présidents.", 'e_ukr_ap_2026', '2026', 'Russie, Ukraine', "En novembre 2026, c'est toujours Moscou qui refuse le cessez-le-feu demandé par Kiev.", 'etabli'),
 ],
 court="Des négociations ont lieu depuis 2022, encore à Abou Dhabi en novembre 2026. En mars 2025, l'Ukraine a accepté un cessez-le-feu de 30 jours ; la Russie a posé des conditions. Moscou exige toujours que Kiev lui cède quatre régions qu'elle n'a même pas entièrement conquises. Accuser Zelensky seul, c'est oublier qui a envahi l'Ukraine.",
 moyen="Il faut négocier, et on négocie : à Istanbul en 2022 et en 2025, à Abou Dhabi en 2026, avec une médiation américaine. Le 11 mars 2025, l'Ukraine a accepté la proposition américaine d'un cessez-le-feu de 30 jours, si la Russie l'appliquait aussi. Deux jours plus tard, Vladimir Poutine a posé des conditions sur le contrôle de la trêve, les livraisons d'armes et la mobilisation ukrainienne.\n\nLes exigences russes n'ont guère changé : en juin 2025, Moscou réclamait la reconnaissance de cinq régions ukrainiennes comme russes, le retrait de l'armée ukrainienne, la neutralité et un plafond pour son armée. En novembre 2026, selon l'AP, la Russie refusait encore un cessez-le-feu général. Kiev refuse de céder son territoire et a jugé en 2022 « impossible » de négocier avec Poutine : ce sont de vraies lignes rouges. Mais la paix est d'abord bloquée par celui qui exige des territoires qu'il n'a pas conquis.",
 detaille="Personne de sérieux ne dit qu'il ne faut pas négocier : la question est de savoir à quelles conditions. Au printemps 2022, à Istanbul, l'Ukraine était prête à une neutralité permanente en échange de garanties de sécurité, selon les chercheurs Samuel Charap et Sergey Radchenko. Mais les deux camps restaient très éloignés sur la taille de l'armée ukrainienne, la Russie a ajouté des exigences, et après la découverte des massacres de Boutcha, les pourparlers ont échoué. Ces chercheurs reconnaissent ne pas savoir si Poutine négociait de bonne foi. Le récit d'une paix sabotée par Boris Johnson contre un pot-de-vin a été démenti en 2026.\n\nIl faut reconnaître les lignes rouges ukrainiennes. Le 4 octobre 2022, après l'annonce par Moscou de l'annexion de quatre régions, un décret de Zelensky a jugé « impossible » de négocier avec Poutine. En novembre 2026, Kiev refuse toujours de céder du territoire ou de limiter son armée. Mais l'Ukraine a repris les pourparlers directs, et le 11 mars 2025 elle a accepté un cessez-le-feu de 30 jours proposé par Washington, à condition que la Russie l'applique aussi. Moscou a posé des conditions et rejeté une trêve préalable aux négociations.\n\nLes exigences russes sont restées maximalistes. Le mémorandum remis à Istanbul le 2 juin 2025 réclame la reconnaissance de la Crimée, de Donetsk, de Louhansk, de Zaporijia et de Kherson comme russes, le retrait total de l'armée ukrainienne, la neutralité, un plafond d'effectifs et l'arrêt de l'aide militaire étrangère. Le plan américain de novembre 2025 en reprenait une partie, ce que les Européens ont refusé. À Abou Dhabi, en novembre 2026, la Russie refusait encore un cessez-le-feu général que Kiev demandait. L'ONU rappelle qu'une paix juste doit respecter l'intégrité territoriale de l'Ukraine. Négocier, oui ; récompenser l'invasion, non.",
 empathie="La guerre dure depuis des années, avec des milliers de morts, et on comprend que beaucoup de gens veuillent qu'elle s'arrête au plus vite. Ce désir de paix est légitime et partagé.",
 legitimes=["L'Ukraine a jugé en 2022 « impossible » de négocier avec Poutine, par décret.", "Kiev refuse de céder du territoire et de limiter son armée, ce qui rend un accord difficile.", "Les négociations de 2022 auraient peut-être pu aboutir si les garanties occidentales avaient été discutées sérieusement."],
 contre=[
  ("En 2022, la paix était signée à Istanbul et l'Occident l'a fait capoter.", "Selon les chercheurs qui ont étudié les documents, les deux camps restaient très éloignés et on ne sait pas si Poutine négociait de bonne foi. Le récit d'un sabotage par Boris Johnson contre un pot-de-vin a été démenti."),
  ("Zelensky refuse de négocier.", "Son gouvernement négocie à Istanbul puis à Abou Dhabi, et il a accepté en mars 2025 un cessez-le-feu de 30 jours. C'est la Russie qui a refusé une trêve sans conditions."),
  ("Il suffit de céder le Donbass pour avoir la paix.", "Moscou exige aussi Zaporijia et Kherson, la neutralité, un plafond pour l'armée et l'arrêt de l'aide occidentale : céder du territoire ne garantit pas que la guerre ne reprendra pas."),
 ],
 questions=["Sais-tu qui a accepté le cessez-le-feu de 30 jours proposé par les États-Unis en mars 2025, et qui l'a refusé ?", "Accepterais-tu de céder une région que l'armée ennemie n'a même pas conquise ?"],
 limites=["L'actualité est très récente : les pourparlers d'Abou Dhabi de novembre 2026 sont décrits à partir d'une seule dépêche de l'AP du 10 novembre ; les articles de franceinfo et France 24 sur leur issue n'ont pas pu être ouverts.", "Le plan américain en 28 points n'a pas été publié officiellement ; il est connu par des fuites rapportées par la presse.", "Les rounds de négociation de mai et juillet 2025 et les trois rounds de 2026 antérieurs à novembre n'ont pas été lus en détail.", "L'analyse de 2022 repose sur un entretien radio avec deux chercheurs, qui présentent leurs conclusions comme provisoires ; l'article de Foreign Affairs n'a pas été lu.", "La déclaration de Djeddah a été lue sur le site du gouvernement ukrainien, partie au conflit.", "Les pages ont été lues à travers un outil qui résume : les citations sont courtes et à revérifier mot pour mot."],
 publics={'convaincus': "Tu veux qu'on négocie ? On négocie : à Istanbul, puis à Abou Dhabi encore ce mois-ci. En mars 2025, Zelensky a accepté un cessez-le-feu de 30 jours ; c'est Poutine qui a posé des conditions. Et Moscou exige toujours des régions entières que son armée n'a même pas conquises : qui bloque, à ton avis ?",
  'indecis': "Vouloir que la guerre s'arrête, c'est légitime. Les deux camps ont des lignes rouges, et Kiev refuse de céder son territoire. Mais l'Ukraine a accepté en 2025 un cessez-le-feu que la Russie n'a pas accepté sans poser de conditions, et les exigences russes vont bien au-delà du front actuel. Une paix durable doit aussi empêcher une nouvelle invasion."},
 a_actualiser='2026-12-15', raison="Suite des pourparlers d'Abou Dhabi de novembre 2026 et évolution de la situation militaire.",
))


